use crate::seeders::database_seeder::SeederContext;
use crate::seeders::helper::file::find_file;
#[allow(unused_imports)]
use anyhow::{Result, anyhow};
use rand::prelude::SliceRandom;
use rustavel_core::helper::datetime::now_ymd_hms;
use rustavel_core::helper::number::random;
use rustavel_core::helper::persian::{persian_lorem_html, persian_slug};
use sqlx::AnyPool;
use std::collections::HashMap;
use std::fmt::format;
use rustavel_core::config::database::DbPoolType;
// model: Product (models live in the app crate and can't be imported here)

pub struct ProductSeeder;

impl ProductSeeder {
    /**
     * Run the database seeds.
     */

    pub async fn run(ctx: SeederContext) -> Result<bool> {
        let mut images: HashMap<u64, Vec<String>> = HashMap::new();
        let cats = get_category(&ctx.pool).await?;
        let cats_slug = get_category_slug(&ctx.pool).await?;
        let cats_parent = get_category_parent(&ctx.pool).await?;

        images.insert(5, find_file("storage/app/public/product/", "mobile*")?);
        images.insert(6, find_file("storage/app/public/product/", "tab*")?);
        images.insert(7, find_file("storage/app/public/product/", "hand*")?);
        images.insert(8, find_file("storage/app/public/product/", "lap*")?);

        let mut a = find_file("storage/app/public/product/", "pc*")?;
        a.extend(find_file("storage/app/public/product/", "iMac*")?);
        images.insert(9, a);

        let mut a = find_file("storage/app/public/product/", "cpu*")?;
        a.extend(find_file("storage/app/public/product/", "case*")?);
        a.extend(find_file("storage/app/public/product/", "speak*")?);
        a.extend(find_file("storage/app/public/product/", "heads*")?);
        images.insert(10, a);

        images.insert(12, find_file("storage/app/public/product/", "head*")?);
        images.insert(13, find_file("storage/app/public/product/", "speak*")?);
        images.insert(14, find_file("storage/app/public/product/", "tv*")?);
        images.insert(15, find_file("storage/app/public/product/", "console*")?);
        images.insert(16, find_file("storage/app/public/product/", "joyst*")?);

        let mut a = find_file("storage/app/public/product/", "vr*")?;
        a.extend(find_file("storage/app/public/product/", "head*")?);
        images.insert(17, a);

        let product_sql = r#"
        INSERT INTO products
        (
            name, slug, description, price, quantity,
            category_id, user_id, image, thumb,
            created_at, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    "#;

        let image_sql = r#"
        INSERT INTO images (product_id, image, thumb)
        VALUES (?, ?, ?)
    "#;
        let rel_sql = "INSERT INTO product_category (product_id, category_id) VALUES (?, ?);";
        let mut rng = rand::rng();

        let now = now_ymd_hms();
        for (cat_id, mut image_list) in images {
            // Prevent duplicate source images
            image_list.sort();
            image_list.dedup();

            // Shuffle images for random secondary image selection
            image_list.shuffle(&mut rng);

            for (index, main_image) in image_list.iter().enumerate() {
                let price: u64 = random(11, 1000) as u64 * 1000000 ;
                let stock = random(0, 120);

                let (name, slug) = persian_slug();
                let user_id = random(1, 10);

                let filename = std::path::Path::new(main_image)
                    .file_name()
                    .unwrap()
                    .to_string_lossy()
                    .into_owned();

                let thumb = format!("storage/product/thumb/{filename}");

                // Insert product
                let result = sqlx::query(product_sql)
                    .bind(format!("{} {}", cats.get(&cat_id).unwrap(), &name))
                    .bind(format!("{}-{}", cats_slug.get(&cat_id).unwrap(), &slug))
                    .bind(persian_lorem_html(true, 120, "<br><br>"))
                    .bind(price)
                    .bind(stock as u64)
                    .bind(cat_id as u64)
                    .bind(user_id as u64)
                    .bind(&main_image.replace("storage/app/public", "storage"))
                    .bind(&thumb)
                    .bind(&now)
                    .bind(&now)
                    .execute(&ctx.pool)
                    .await?;

                let product_id = result.last_insert_id();

                // Main image + 1 or 2 secondary images
                let mut selected = vec![main_image.clone()];

                let available: Vec<&String> = image_list
                    .iter()
                    .enumerate()
                    .filter(|(i, _)| *i != index)
                    .map(|(_, image)| image)
                    .collect();

                let extra_count = random(1, 2).min(available.len() as i32);

                let mut extras = available;
                extras.shuffle(&mut rng);

                for image in extras.into_iter().take(extra_count as usize) {
                    selected.push(image.clone());
                }

                // insert main category
                sqlx::query(rel_sql)
                    .bind(product_id )
                    .bind(cat_id  as u64)
                    .execute(&ctx.pool)
                    .await?;
                // insert parent category
                sqlx::query(rel_sql)
                    .bind(product_id )
                    .bind(cats_parent.get(&cat_id).unwrap())
                    .execute(&ctx.pool)
                    .await?;

                // Insert all product images
                for image in selected {
                    let filename = std::path::Path::new(&image)
                        .file_name()
                        .unwrap()
                        .to_string_lossy()
                        .into_owned();

                    let thumb = format!("storage/product/thumb/{filename}");

                    sqlx::query(image_sql)
                        .bind(product_id as u64)
                        .bind(&image.replace("storage/app/public", "storage"))
                        .bind(&thumb)
                        .execute(&ctx.pool)
                        .await?;
                }
            }
        }

        Ok(true)
    }
}

async fn get_category(pool: &DbPoolType) -> Result<HashMap<u64, String>, sqlx::Error> {
    let sql_cats = "SELECT id, name FROM categories";

    let rows: Vec<(u64, String)> = sqlx::query_as(sql_cats).fetch_all(pool).await?;

    Ok(rows.into_iter().collect())
}
async fn get_category_slug(pool: &DbPoolType) -> Result<HashMap<u64, String>, sqlx::Error> {
    let sql_cats = "SELECT id, slug FROM categories";

    let rows: Vec<(u64, String)> = sqlx::query_as(sql_cats).fetch_all(pool).await?;

    Ok(rows.into_iter().collect())
}
async fn get_category_parent(pool: &DbPoolType) -> Result<HashMap<u64, u64>, sqlx::Error> {
    let sql_cats = "SELECT id, parent_id FROM categories WHERE parent_id IS NOT NULL";

    let rows: Vec<(u64, u64)> = sqlx::query_as(sql_cats).fetch_all(pool).await?;

    Ok(rows.into_iter().collect())
}
